-- 0005: Stillness Co. import (client, people, project, conversations, messages, entries, tasks, issues)
-- Generated from solicate-import-draft.md + WhatsApp export (_chat.txt).
-- Idempotent: every insert uses ON CONFLICT DO NOTHING keyed on deterministic IDs.
-- created_by_id / owner_id / sender_user_id resolve to the first active internal app_user.
-- Message bodies are verbatim from the WhatsApp export (250 messages; the draft's 193 rows were a curated index).

do $guard$
begin
  if not exists (select 1 from public.app_users where is_active = true) then
    raise exception 'No active app_user exists. Sign in to the app once so the auth trigger creates your app_users row, then re-run.';
  end if;
end $guard$;

